  "6.4": {
    number:"6.4", shortTitle:"隱私安全合規", title:"大數據隱私保護、安全與合規", mark:"SAFE", pages:"6-30～6-42",
    summary:"在 AI 全生命週期辨識直接與準識別資訊，選擇匿名化、差分隱私與存取控制，並以合法基礎、目的限制、稽核及跨部門治理確保資料可用且合規。",
    footer:"去識別不是一次性動作；需同時評估重識別風險、資料效用、合法基礎與持續治理。",
    sections:[
      {title:"隱私風險全貌",short:"風險全貌",flow:[["資料盤點","PII、敏感與準識別"],["風險評估","重識別、外洩與濫用"],["合法基礎","同意、契約、義務等"],["最小化","目的、欄位與保存期限"],["技術保護","匿名化、加密、DP"],["權限稽核","最小權限與日誌"],["治理回應","委員會、教育與事件處理"]]},
      {title:"識別與重識別風險",short:"識別風險",table:{headers:["類型","例子","風險"],rows:[["直接識別資訊","姓名、身分證號、電話、裝置 ID","單一欄位即可指向個人"],["準識別資訊","性別、出生年月、郵遞區號、瀏覽紀錄","組合後可能重識別"],["敏感資料","健康、金融、生物特徵、政治宗教","傷害高、通常需更嚴格保護"],["推論資訊","模型由行為推知疾病或偏好","原始欄位不敏感也可能產生敏感結論"]]}},
      {title:"基礎匿名化",short:"匿名化",table:{headers:["方法","作法","限制"],rows:[["Masking","遮蔽部分字元","可能仍可由其他欄位連結"],["Pseudonymization","以代碼取代身份","對照表存在時仍可還原"],["Generalization／Bucketing","降低精度，如年齡區間","粒度過細仍可識別，過粗損失效用"],["Suppression","刪除高風險欄位／紀錄","資料完整性下降"],["Aggregation","只提供群體統計","小群體仍需最小群組門檻"]]}},
      {title:"進階隱私技術",short:"隱私技術",table:{headers:["技術","核心","取捨"],rows:[["k-anonymity","每組準識別組合至少有 k 人","不防同質性與背景知識攻擊"],["l-diversity／t-closeness","要求敏感值多樣或接近整體分佈","效用與計算成本"],["Differential Privacy","加入受控噪音，限制單筆資料影響","ε 越小隱私越強但準確度下降"],["Federated Learning","資料留在端點，只交換更新","梯度仍可能洩漏；需 Secure Aggregation／DP"],["Homomorphic Encryption","在密文上計算","保護強但運算昂貴"]]}},
      {title:"合規處理原則",short:"合規原則",cards:[["LAW","合法公平透明","有明確法律依據並向資料主體說明。"],["PUR","目的限制","只用於蒐集時聲明或相容目的。"],["MIN","資料最小化","只收集、使用達成目的必要資料。"],["ACC","正確與期限","維持資料正確，期滿刪除或匿名化。"],["SEC","完整與保密","以技術與組織措施防止未授權存取。"],["ACCOUNT","問責","保留政策、紀錄、DPIA 與稽核證據。"]]},
      {title:"合法基礎與資料主體權利",short:"合法基礎",table:{headers:["面向","重點"],rows:[["明確同意","自由、具體、知情、可撤回，不可預先勾選"],["契約／法律義務","處理確為履約或法定要求所必要"],["正當利益","需做利益衡量且不可壓過個人權益"],["資料主體權利","查閱、更正、刪除、限制、反對、可攜與自動決策保障"],["DPIA","高風險處理前評估影響與降低措施"]]}},
      {title:"安全控制與事件管理",short:"安全控制",table:{headers:["層面","控制"],rows:[["身分與權限","MFA、RBAC／ABAC、最小權限、JIT"],["資料保護","傳輸與靜態加密、金鑰管理、Tokenization"],["網路與平台","分區、Zero Trust、弱點管理、備援"],["監控稽核","不可竄改日誌、DLP、異常存取告警"],["事件回應","偵測、隔離、調查、通報、復原與事後改善"]]}},
      {title:"企業治理",short:"企業治理",cards:[["POL","政策制度","資料分類、使用規範、保存／刪除與第三方管理。"],["COM","治理委員會","法務、資安、資料科學、IT 與業務共同審議。"],["ROLE","責任角色","CAIO、DPO、Data Steward、System Owner。"],["TRAIN","文化訓練","依角色持續進行隱私、安全與 AI 合規教育。"]]},
      {title:"考題與易混淆",short:"考題重點",table:{headers:["主題","正確辨析"],rows:[["匿名化 vs 假名化","假名化可用對照表還原，仍屬個資保護範圍"],["k-anonymity","保證準識別群組大小，不保證敏感值多樣"],["Differential Privacy","噪音保護的是單筆存在與否的影響，不是把資料全部加密"],["Federated Learning","資料不集中，但仍需防梯度洩漏與惡意端點"],["同意","不是唯一合法基礎，也不能用模糊同意涵蓋所有用途"],["治理","不是只有資安部門責任，而是跨部門制度"]]}}
    ],
    terms:[["PII","Personally Identifiable Information","可直接或間接識別個人的資訊。"],["Quasi-identifier","準識別資訊","組合後可能識別個人的欄位。"],["Re-identification","重識別","由去識別資料重新推得個人身份。"],["Masking","遮蔽","隱藏部分識別資訊。"],["Pseudonymization","假名化","以代碼取代身份並另存對照。"],["Generalization","泛化","降低資料精度以減少識別性。"],["k-anonymity","k 匿名","每組準識別組合至少有 k 筆。"],["Differential Privacy","差分隱私","以受控噪音限制單筆資料影響。"],["Privacy Budget","ε","差分隱私的隱私損失參數。"],["Federated Learning","聯邦學習","資料留在端點進行協同訓練。"],["Homomorphic Encryption","同態加密","允許在密文上計算。"],["DPIA","資料保護影響評估","高風險處理前的系統性隱私評估。"],["Least Privilege","最小權限","只授予完成任務必要權限。"],["Data Steward","資料管理員","負責資料定義、品質、使用與治理。"]]
  }
